window.TRACE_DECK = {"content":{"_ai_assisted":"Written with Claude Code (Anthropic). See docs/AI_USAGE.md.","_note":"Source of truth for the TRACE pitch deck. Edit here, then run: python3 deck/build.py","meta":{"title":"TRACE","event":"2026 Carolina Data Challenge · Graduate Track","theme":"AI for Social Good","runtime_target_seconds":285,"demo_seconds":120,"qa_seconds":120,"format_note":"7:00 total (deck + live demo) + 2:00 Q&A. The live demo follows the deck."},"speakers":[{"slot":"S1","name":"William Keffer","section":"The Problem","seconds":65},{"slot":"S2","name":"Ismail Gasmi","section":"The Idea","seconds":60},{"slot":"S3","name":"Markandeya Yalamanchi","section":"How It Works","seconds":70},{"slot":"S4","name":"Adrian Hito","section":"Proof, Impact & Handoff","seconds":90}],"slides":[{"id":"cold-1","act":"I","speaker":"S1","seconds":8,"theme":"void","blocks":[{"type":"lines","scale":"xl","items":["Afghanistan grew four fifths","of the world's illicit opium."]},{"type":"source","text":"UNODC World Drug Report 2026 · about 80% of global illicit opium production before 2022"}],"cues":["Hold two full seconds of silence before you speak.","Say it flat. The fact does the work.","Four fifths. Not 'most' — the number is the hook."]},{"id":"cold-2","act":"I","speaker":"S1","seconds":7,"theme":"void","blocks":[{"type":"lines","scale":"xl","items":["In April 2022, one decree"]},{"type":"lines","scale":"xl","tone":"accent","items":["cut it by 95%."]},{"type":"source","text":"Taliban decree 3 April 2022, enforced from the 2022/23 planting season · Afghan opium production 6,200 t (2022) → 333 t (2023) · UNODC Afghanistan Opium Survey"}],"cues":["Beat before '95%'.","Be precise if asked: 95% is Afghan *production*, and Afghanistan was ~80% of world supply.","Never say 'erased the world's opium' — about 12,000 tonnes of stockpile kept flowing."]},{"id":"cold-3","act":"I","speaker":"S1","seconds":6,"theme":"void","blocks":[{"type":"lines","scale":"l","items":["The drugs didn't stop."]},{"type":"lines","scale":"xl","tone":"accent","items":["They moved."]},{"type":"sub","text":"And for three years, nobody could tell the countries they moved toward that they were coming."}],"cues":["'They moved' is the thesis of the entire project.","Land it, then go straight to the lag slide."]},{"id":"lag","act":"I","speaker":"S1","seconds":12,"theme":"void","blocks":[{"type":"kicker","text":"The world's drug-harm data, today"},{"type":"lagrow","items":[{"label":"Intentional homicide rate","year":"2022","code":"VC.IHR.PSRC.P5 · 142 of 243 have nothing newer"},{"label":"HIV incidence, 15–49","year":"2024","code":"SH.HIV.INCD.ZS · modelled, not surveyed"},{"label":"Poverty headcount","year":"2022","code":"SI.POV.DDAY · 59% have nothing newer"},{"label":"Cannabis use prevalence","year":"2017","code":"UNODC WDR annex 1.2 · 11 countries have a 2024+ estimate"}]},{"type":"lines","scale":"m","items":["Development data runs two to four years late.","Drug-use prevalence, for the median country,","runs nine."]},{"type":"source","text":"Median economy's most recent value, World Bank Indicators API, retrieved 2026-09-26 · UNODC World Drug Report 2026 statistical annex"}],"cues":["These are median-country figures we pulled from the live API, not the best-reported country.","Nine years is the number to land. Say it and stop.","If challenged: the WDR headline year is 2024, but that rests on estimates most countries last made in 2017."]},{"id":"late-detection","act":"I","speaker":"S1","seconds":11,"theme":"void","blocks":[{"type":"kicker","text":"What the delay costs"},{"type":"lines","scale":"l","items":["Scott County, Indiana.","HIV spread undetected for four years."]},{"type":"statgrid","compact":true,"items":[{"value":"215","label":"people infected","source":"undetected from 2011; emergency declared 26 March 2015"},{"value":"<56","label":"if caught in 2013","source":"modelled counterfactual"},{"value":"<10","label":"if the 2011 hepatitis C signal had been read","source":"the warning was already in the data"}]},{"type":"sub","text":"This is the pattern, not the exception. In three of four documented outbreaks a hepatitis C or injecting signal preceded the HIV outbreak by one to four years and was not collected, not analysed, or not acted on. Across the modelled outbreaks, <em>60 to 95 percent</em> of infections are attributed to the delay in detection and response — not to the drugs."},{"type":"source","text":"Glasgow 2015: 62.7% of cases averted had services scaled at detection · Athens: HIV among people who inject drugs rose from under 1% (2010) to 16.5% (2013); intervening two years earlier modelled to avert 1,110 cases and €35–53M"}],"cues":["Two sentences only. The numbers do the work.","The counterfactual is the point: almost all of that epidemic was the delay, not the drugs.","Do not editorialise. Let '<10' sit there."]},{"id":"transit","act":"I","speaker":"S1","seconds":11,"theme":"void","blocks":[{"type":"kicker","text":"And it lands on people who never chose it"},{"type":"lines","scale":"l","items":["A trafficking route is not a line on a map.","It is a country that inherits","a drug crisis it did not create."]},{"type":"list","columns":3,"items":[{"title":"Local use rises","text":"Transit countries become consumer markets. Product is paid out in product."},{"title":"Violence follows","text":"Corridor control is contested territory, and the homicide data proves it late."},{"title":"HIV follows","text":"Injecting populations appear years before any surveillance system sees them."}]}],"cues":["This is the social-good core. Slow down here.","Name the asymmetry: the harm lands furthest from where the decisions get made.","Handoff is coming — set up the next line."]},{"id":"boundary","act":"I","speaker":"S1","seconds":10,"theme":"void","blocks":[{"type":"lines","scale":"l","items":["So we built an instrument."]},{"type":"rule"},{"type":"lines","scale":"m","tone":"dim","items":["It is not an enforcement tool."]},{"type":"sub","text":"TRACE shows where flows and harms are heading, never where enforcement is weakest. No least-watched-route feature, no lowest-risk-corridor query, no ranking that helps anyone move product. That boundary is written into our engineering rules and enforced in code review."},{"type":"source","text":"CLAUDE.md · 'Design boundary (non-negotiable)' · committed before the first line of model code"}],"cues":["Say the boundary out loud. Judges will be thinking it — answer it before they ask.","It is a design constraint we shipped, not a disclaimer we added.","Hand off: 'Here is what we built instead.'"],"handoff":"Here's what we built instead."},{"id":"wordmark","act":"II","speaker":"S2","seconds":8,"theme":"reveal","blocks":[{"type":"wordmark","text":"TRACE"},{"type":"lines","scale":"m","items":["{{project.one_liner}}"]}],"cues":["Let the arcs resolve before you say the name.","One line, then stop talking for a beat."]},{"id":"reframe","act":"II","speaker":"S2","seconds":10,"theme":"atlas","blocks":[{"type":"swap","from":"Where are the drugs?","to":"Where does the harm land next?"},{"type":"sub","text":"Every other tool in this space answers the first question, for police. And every existing harm forecast is <em>autoregressive</em> — it predicts more of an epidemic a country already has. TRACE answers the second question, for public health, from outside: it forecasts harm in countries that have not had the epidemic yet, from the corridor that is about to open."}],"cues":["This swap is the innovation claim. Make it the loudest sentence in your section.","'Autoregressive' is the word that separates us: everyone else forecasts more of what a country already has.","The first question serves enforcement. The second serves prevention."]},{"id":"terminal-hero","act":"II","speaker":"S2","seconds":14,"theme":"atlas","blocks":[{"type":"kicker","text":"One workspace. Every corridor."},{"type":"shot","sid":"route-map","aspect":"16/9","caption":"Atlas — corridor arcs coloured by country exposure, width by corridor volume, 2011–{{counts.latest_year}} scrubber, Observed / Forecast toggle","spec":"Full-bleed Atlas capture, 1440×960, Forecast on, all substances.","maxvh":70}],"cues":["This is the real thing, captured from the running app — say so.","Colour is country exposure, width is corridor volume. One sentence, then let it breathe.","Do not narrate the UI. The live demo does that."]},{"id":"six-screens","act":"II","speaker":"S2","seconds":16,"theme":"atlas","blocks":[{"type":"kicker","text":"Six workspaces, one ⌘K"},{"type":"shotgrid","items":[{"sid":"risk-board","title":"RISK BOARD","text":"Forty countries ranked on exposure, vulnerability and protection, with trend sparklines","spec":"Risk board, 1440×960, sorted by score, sparklines visible."},{"sid":"country-screen","title":"COUNTRY","text":"COL &lt;GO&gt; — 2025 Colombia profile, score 64.5, harm-reduction coverage, every figure carrying its source and year","spec":"Colombia country profile, 1440×960, all panels populated."},{"sid":"simulator","title":"SCENARIOS","text":"Cut Colombian cultivation by half: 25 corridors change, 20 risk scores move","spec":"Saved Colombia −50% scenario showing changed routes and risk deltas."},{"sid":"livewire","title":"LIVE WIRE","text":"Classified events drop a pin on the map; anomalies flag where the model was wrong","spec":"Live wire feed with a story selected and its beacon pinned."},{"sid":"market-board","title":"MARKETS","text":"Fifty-seven price series; missing years render as unavailable, never as zero","spec":"Markets panel, drug and market filters applied."},{"sid":"experiment","title":"EXPERIMENT","text":"Afghanistan 2022, predicted against actual, on saved pipeline metrics","spec":"Experiment view, 1440×960."}]}],"cues":["Name them fast — six in fifteen seconds, don't dwell.","The point is breadth: this is a product, not a notebook.","Everything is keyboard-driven — ⌘K goes anywhere."]},{"id":"commands","act":"II","speaker":"S2","seconds":12,"theme":"atlas","blocks":[{"type":"commandline","items":[{"cmd":"COL <GO>","out":"Colombia 2025 · risk 64.5 · harm-reduction coverage · every figure sourced and dated"},{"cmd":"COMPARE COL PER","out":"64.5 against 73.1 · side by side"},{"cmd":"SHOCK COL CULTIVATION -50%","out":"25 corridors change · 20 risk scores move"}]},{"type":"sub","text":"Free text is parsed into typed commands by Jev. Anything a judge can type, the workspace answers — and refuses, visibly, what it has no data for."}],"cues":["Read one command aloud, not all three.","Every one of these is verified working in the shipped app.","Hand off: 'None of this works without the data underneath it.'"],"handoff":"None of this works without the data underneath it."},{"id":"data-spine","act":"III","speaker":"S3","seconds":16,"theme":"atlas","blocks":[{"type":"kicker","text":"The data spine"},{"type":"statgrid","items":[{"value":"{{counts.indicators}}","label":"World Bank indicators","source":"Indicators API, sources 2 + 3, pulled programmatically"},{"value":"{{counts.economies}}","label":"economies","source":"aggregates filtered out, 2005–2026"},{"value":"{{counts.ids_cases}}","label":"UNODC seizure cases","source":"Individual Drug Seizures, 2011–2026"},{"value":"{{counts.corridors}}","label":"corridors modelled","source":"× 14 years, seizure-anchored allocation"},{"value":"{{counts.oc_index}}","label":"countries, OC Index","source":"GI-TOC 2021 / 2023 / 2025 editions"},{"value":"{{counts.hri}}","label":"countries, harm reduction","source":"Harm Reduction International GSHR 2024"}]}],"cues":["These are counts from our own pipeline — every one is checkable in the repo.","The World Bank API is called programmatically with explicit source IDs. That's the track requirement and we meet it literally.","Don't read all six. Read two."]},{"id":"wb-load-bearing","act":"III","speaker":"S3","seconds":16,"theme":"atlas","blocks":[{"type":"kicker","text":"The World Bank data is load-bearing, not decorative"},{"type":"list","columns":5,"numbered":true,"items":[{"title":"Market mass","text":"GDP, GDP per capita PPP, population set the size of every node in the gravity model."},{"title":"Route friction","text":"Governance, customs efficiency, port TEU, air traffic, trade openness explain why a flow takes one country and not its neighbour."},{"title":"Vulnerability","text":"Youth unemployment, NEET, poverty, Gini, health spend decide how badly a route's arrival hurts."},{"title":"Validation targets","text":"Homicide, HIV incidence, refugee flows are what the spillover hypothesis is tested against."},{"title":"Detection-bias control","text":"Rule of law and customs efficiency separate 'more drugs moving' from 'better at catching them'."}]},{"type":"source","text":"Remove the World Bank layer and the model has no market sizes, no friction, and no vulnerability. It stops being a model."}],"cues":["This slide is aimed straight at the Graduate-track judge.","Role 5 is the one they won't expect — spend your time there.","If asked: governance codes are GOV_WGI_*.EST on source 3. The old CC.EST family is archive-only now. We found that by verifying against the live API."]},{"id":"model","act":"III","speaker":"S3","seconds":16,"theme":"atlas","blocks":[{"type":"kicker","text":"Two models, and we report both"},{"type":"pipeline","steps":[{"step":"BASELINE","title":"PPML gravity","text":"Poisson pseudo-maximum-likelihood, the standard in trade economics. GDP, population, distance, contiguity, price gap."},{"step":"MAIN","title":"LightGBM hurdle","text":"(a) will this corridor be active next year, (b) how much moves if it is. Lagged volume, cultivation upstream, governance, logistics, OC Index, conflict."},{"step":"EXPLAIN","title":"SHAP per corridor","text":"Every predicted shift comes with its drivers, in plain language, on the map."}]},{"type":"source","text":"Santos Silva & Tenreyro (2006) · Ke et al. (2017) · Lundberg & Lee (2017)"}],"cues":["The hurdle structure exists because most corridors are zero in most years. Say that — it shows you understand your own data.","SHAP is what turns a prediction into something a health ministry can act on."]},{"id":"jev","act":"III","speaker":"S3","seconds":12,"theme":"atlas","blocks":[{"type":"kicker","text":"Live Wire · the layer that beats the lag"},{"type":"lines","scale":"m","items":["Official data is years late.","News is minutes late."]},{"type":"list","columns":3,"items":[{"title":"Ingest","text":"GDELT polled every 15 minutes, deduped, filtered to drug events worldwide."},{"title":"Classify","text":"Jev — TypeSafe's System One model — answers seven typed questions per article in one parallel pass, 70–500 ms: event type, drug, origin, transit, destination, size. Each answer carries a confidence score. Pinned to jev-1.13.0."},{"title":"Flag","text":"A confident event on a corridor the model gave under 10% probability is an anomaly — the model is wrong, and it says so on the map."}]},{"type":"source","text":"Classifier sits behind a JevClassifier interface; the real client activates the moment the key lands. Confidence is a routing signal, not a probability — below 0.6 nothing is shown, and events on low-probability corridors are flagged rather than trusted."}],"cues":["The anomaly flag is the best idea in the system. Spend your last seconds there.","A model that announces its own misses is a model you can trust.","If asked why not a normal LLM: schema conformance is table stakes now — the honest answer is latency and cost per article at stream volume, not 'typed output'.","Do NOT say 'calibrated'. TypeSafe publishes no calibration metrics; independent testing puts it near 0.02–0.03 in-distribution and ~4x worse out of it."]},{"id":"honesty-method","act":"III","speaker":"S3","seconds":10,"theme":"atlas","blocks":[{"type":"kicker","text":"The objection we designed around"},{"type":"lines","scale":"m","items":["Seizures measure enforcement,","not trafficking."]},{"type":"sub","text":"Correct. So no corridor rests on seizures alone. Every edge carries a 0–100 confidence score built from six independent signals: seizures present, price gradient in the expected direction, OC Index market scores at both ends, live news hits, and cultivation upstream. Detection bias is controlled with rule of law and customs efficiency. Low-confidence corridors are drawn faint, and we say so."},{"type":"source","text":"Every known limitation is written into docs/SYSTEM_DESIGN.md §5 and docs/BLOCKERS.md, not hidden."}],"cues":["Saying the weakness first is what makes the rest credible.","Hand off on strength: 'So — does it actually work?'"],"handoff":"So — does any of it actually work?"},{"id":"backtest","act":"IV","speaker":"S4","seconds":16,"theme":"atlas","blocks":[{"type":"kicker","text":"Backtest · trained through 2019, predicting 2020–{{counts.latest_year}}"},{"type":"compare","items":[{"label":"LightGBM hurdle","value":"{{metrics.hurdle_auc}}","pct":92,"tone":"up","note":"AUC, corridor activation"},{"label":"PPML gravity baseline","value":"{{metrics.gravity_auc}}","pct":61,"tone":"dim","note":"AUC, same corridors, same years"}]},{"type":"sub","text":"We ran the standard economics baseline against ourselves and published both numbers — Spearman {{metrics.spearman}}, precision@20 {{metrics.precision_at_20}}. The gap is what the World Bank development layer buys you."}],"cues":["Do not say 'our model is accurate'. Say 'here is our model against the field standard, on held-out years'.","The baseline existing at all is the credibility move."]},{"id":"afghan","act":"IV","speaker":"S4","seconds":22,"theme":"atlas","blocks":[{"type":"kicker","text":"The natural experiment · Afghanistan, 2022"},{"type":"shot","sid":"experiment","aspect":"16/10","caption":"Experiment — cultivation collapse against corridor response, on saved pipeline metrics","spec":"Experiment view, 1440×960, Actual selected.","maxvh":40},{"type":"statgrid","compact":true,"items":[{"value":"{{metrics.afghan_hit}}","label":"corridors called correctly","source":"direction of shift, held-out"},{"value":"{{metrics.sea_pred}}","label":"predicted SE Asia share","source":"up from {{metrics.sea_base}} pre-ban"},{"value":"{{metrics.sea_actual}}","label":"actual SE Asia share","source":"our corridor allocation on 2023–24 seizure and cultivation data"}]},{"type":"sub","text":"We trained through 2021 — before the ban — injected the cultivation collapse as a shock, and asked the model where heroin would go. Then we checked it against what the later data showed."}],"cues":["This is the product's own Experiment screen — the chart is theirs, not a slide.","We trained through 2021. The model never saw the answer. That is the whole point.","Strongest twenty seconds you have. Do not rush it."]},{"id":"null-result","act":"IV","speaker":"S4","seconds":16,"theme":"atlas","blocks":[{"type":"kicker","text":"And the result that didn't go our way"},{"type":"lines","scale":"m","items":["We tested our own core hypothesis.","It did not hold."]},{"type":"sub","text":"Route exposure alone does not predict a later rise in homicide or HIV once you control for vulnerability. We committed that the day we found it. Published work lands in the same place: a 2026 panel of 95 countries finds the cocaine–homicide link appears <em>between</em> countries but not <em>within</em> them — structural position on a corridor, not year-to-year flow. So being on a route is not destiny. Being on a route without services, jobs or health spending is. That is why the risk score has three columns and not one, and why this argues for harm reduction rather than interdiction."},{"type":"source","text":"README.md T6, committed before this slide existed · corroborated by ‘Which Illegal Markets Kill?’, European Journal on Criminal Policy and Research (2026), 95 countries, 2021–2025"}],"cues":["Deliver as strength, not apology. Eye contact, steady pace.","Key line: the effect is between countries, not within them — which is exactly what a panel model would miss.","Teams that hide null results lose to teams that report them.","If pressed on the negative sign, concede the enforcement-capacity confound before they raise it."]},{"id":"impact","act":"IV","speaker":"S4","seconds":14,"theme":"atlas","blocks":[{"type":"kicker","text":"What an early-warning layer makes possible"},{"type":"list","columns":4,"items":[{"title":"Harm reduction orgs","text":"Place naloxone, needle exchange and OAT ahead of the curve instead of behind it — against the 93 countries where we know coverage exists and the ones where it doesn't."},{"title":"Public health ministries","text":"See exposure rising two years before the HIV surveillance data would have shown it."},{"title":"Journalists & researchers","text":"Public UN data currently locked in PDFs and portals, in one free queryable instrument."},{"title":"Policymakers","text":"Evidence from real natural experiments — bans, legalization — instead of ideology."}]},{"type":"source","text":"Every input is public data. TRACE ships open, so the countries with the least capacity to build this get it anyway."}],"cues":["Keep these conditional — 'makes possible', not 'is being used by'.","The last line is the ungatekeeping argument. It matters to this rubric."]},{"id":"roadmap","act":"IV","speaker":"S4","seconds":12,"theme":"atlas","blocks":[{"type":"kicker","text":"Where this goes"},{"type":"roadmap","items":[{"when":"Now","what":"{{status.shipped_short}}"},{"when":"+3 months","what":"Live Jev key, fentanyl module, ACLED conflict events, public read-only API"},{"when":"+6 months","what":"Wastewater and EUDA price feeds, weekly retrain, per-country alert subscriptions"},{"when":"+12 months","what":"Deployment with a harm-reduction partner in one transit corridor, measured against real service placement"}]}],"cues":["Read the dates as a plan, not a promise.","One sentence per row, maximum."]},{"id":"close","act":"IV","speaker":"S4","seconds":8,"theme":"void","blocks":[{"type":"lines","scale":"l","tone":"dim","items":["Harm reduction usually arrives","after the crisis."]},{"type":"lines","scale":"xl","tone":"accent","items":["TRACE lets it arrive before."]}],"cues":["Pause before the last line. Then say it and stop.","Do not add anything after it."]},{"id":"handoff","act":"IV","speaker":"S4","seconds":2,"theme":"void","blocks":[{"type":"wordmark","text":"TRACE","small":true},{"type":"lines","scale":"m","items":["Let us show you."]},{"type":"source","text":"→ live demo"}],"cues":["Hit this and go straight into the demo. No pause, no 'any questions'.","Terminal should already be open on the second machine."]}]},"data":{"project":{"name":"TRACE","one_liner":"A Bloomberg terminal for the global drug trade that predicts where the next drug crisis will hit, before it arrives.","tagline":"Early warning for the countries that never chose to be on the route."},"counts":{"indicators":"24","economies":"217","ids_cases":"2.3M","corridors":"676","oc_index":"193","hri":"197","risk_countries":"217","latest_year":"2024","first_year":"2011","sources":"8"},"metrics":{"hurdle_auc":"0.92","gravity_auc":"0.61","afghan_hit":"12/14","sea_base":"5%","sea_pred":"13%","sea_actual":"14%","train_through":"2019","afghan_train_through":"2021","spearman":"0.67","precision_at_20":"0.50","afghan_right":"12","afghan_of":"14"},"charts":{"afghan":{"series":[{"id":"afg_cultivation","label":"Afghanistan","unit":"ha","points":[{"x":2015,"y":183000.0},{"x":2016,"y":201000.0},{"x":2017,"y":328000.0},{"x":2018,"y":263000.0},{"x":2019,"y":163000.0},{"x":2020,"y":224000.0},{"x":2021,"y":177000.0},{"x":2022,"y":233000.0},{"x":2023,"y":10800.0},{"x":2024,"y":12800.0},{"x":2025,"y":10200.0}]},{"id":"mmr_cultivation","label":"Myanmar","unit":"ha","points":[{"x":2015,"y":55500.0},{"x":2017,"y":41000.0},{"x":2018,"y":37300.0},{"x":2019,"y":33100.0},{"x":2020,"y":29500.0},{"x":2021,"y":30200.0},{"x":2022,"y":40100.0},{"x":2023,"y":47100.0},{"x":2024,"y":45200.0},{"x":2025,"y":53100.0}]}],"ban_year":2022,"title":"Afghanistan 2022 opium ban"}},"provenance":{"built_from":"defaults","metrics":"README.md (live run)","afghan":"contracts/fixtures/afghan_ban.json"},"screenshots":{"route-map":"../frontend/design/qa/atlas-desktop.jpg","experiment":"../frontend/design/qa/experiment-desktop.jpg"},"placeholders":[{"sid":"country-screen","title":"Country Screen — Colombia","needs":"Country Screen"},{"sid":"risk-board","title":"Spillover Risk Board — RISK TOP 20","needs":"Risk Board"},{"sid":"simulator","title":"Shock Simulator mid-run","needs":"Simulator UI"},{"sid":"livewire","title":"Live Wire feed with one anomaly","needs":"Live Wire panel"},{"sid":"market-board","title":"Market Board price tickers","needs":"Market Board"}],"status":{"shipped":[{"label":"Spec, docs, handoff","owner":"planning session","status":"done"},{"label":"API contract + fixtures","owner":"backend","status":"done (`contracts/`)"},{"label":"backend scaffold","owner":"backend","status":"done (uv, Python 3.11, `trace` CLI)"},{"label":"World Bank ingest","owner":"backend","status":"done (24 indicators, 217 economies, 2005-2026, `wb_manifest.json`)"},{"label":"external ingest (UNODC, OC Index, HRI, CEPII)","owner":"backend","status":"done (IDS 2.3M cases, WDR annex, OC Index x3, HRI 197 countries, CEPII; see BLOCKERS.md)"},{"label":"edges + confidence","owner":"backend","status":"done (676 corridors x 2011-2024, seizure-anchored allocation, 6-signal confidence)"},{"label":"route models + backtest + Afghan ban test","owner":"backend","status":"done (hurdle AUC 0.92 vs gravity 0.61; Afghan ban 12/14 corridors, SEA share 5%->13% pred vs 14% actual)"},{"label":"spillover risk","owner":"backend","status":"done (217 countries x 2011-2025; hypothesis not supported, see metrics)"},{"label":"export + API","owner":"backend","status":"done (precomputed JSON, FastAPI, contract tests)"},{"label":"Live Wire (mock Jev)","owner":"backend","status":"done (JevClassifier + mock, GDELT poller with replay fallback, REST + WS)"},{"label":"shock simulator","owner":"backend","status":"done (structured + plain-English shocks, command bar)"}],"pending":[{"label":"Frontend shell + map","owner":"frontend","status":"not started"},{"label":"Country Screen + Risk Board","owner":"frontend","status":"not started"},{"label":"Simulator, Live Wire, Market Board","owner":"frontend","status":"not started"}],"frontend_built":true,"shipped_short":"Pipeline, models, backtests, API, Live Wire and the workspace all shipped","shipped_count":11,"pending_count":3},"git":{"sha":"91e3488","subject":"deck: rebuild Act I on the real detection-delay evidence","when":"2026-09-26T21:00:49+00:00","count":"35"},"built_at":"2026-09-26 21:00 UTC"}};
